/// `params.require(:bot).permit(:name, :avatar, :webhook_url)`.
fn bot_params(c: &Ctx) -> Result<BotParams> {
    let bot = c.params.require("bot")?;
    let permitted = bot.permit(&permit_keys(&["name", "avatar", "webhook_url"]));
    let name = permitted.get("name").and_then(Param::to_s);
    let webhook_url = permitted.get("webhook_url").and_then(Param::to_s);
    let avatar = Assignment::from_params(&permitted, "avatar")?;
    Ok(BotParams { name, webhook_url, avatar })
