use campfire_db::{Account, Room, RoomType};

use super::default::default;
use super::toolkit::{NOW, Seed, Upload, days, minutes};

/// `first_run`: the schema only, no account and no users; the sign-in page redirects to
/// `/first_run`.
pub fn first_run(_: &mut Seed) -> anyhow::Result<()> {
    Ok(())
}

/// `restricted`: `default` with "Must be admin to create new rooms" switched on, as
/// `AccountsController#update` does it.
pub fn restricted(s: &mut Seed) -> anyhow::Result<()> {
    s.based_on("default", default)?;
    s.at(NOW - days(8));
    s.write(|tx| {
        let mut account = first_account(tx.conn())?;
        account.update(tx, None, None, Some(&[("restrict_room_creation_to_administrators", "true")]))
    })
}

/// `custom_styles`: `default` with a branded account: a logo, and custom CSS that redefines every
/// custom property in `colors.css`, for light and dark.
pub fn custom_styles(s: &mut Seed) -> anyhow::Result<()> {
    s.based_on("default", default)?;
    let account = first_account(s.conn())?.id;
    s.at(NOW - days(10));
    s.attach_logo(account, Upload::Fixture("black_hole.jpg", "image/jpeg"))?;
    s.at(NOW - days(9));
    s.write(|tx| first_account(tx.conn())?.update(tx, None, Some(Some(CUSTOM_STYLES)), None))
}

/// `crowd`: `default` plus 520 more members, past every list threshold: the room user filter
/// (more than 20), the direct-ping placeholders (20), and the account user list's second page (500
/// per page).
pub fn crowd(s: &mut Seed) -> anyhow::Result<()> {
    const FIRST: [&str; 20] = [
        "Ada", "Ben", "Cleo", "Dev", "Eli", "Fay", "Gus", "Hana", "Ivo", "Jun", "Kai", "Lea", "Milo", "Nia", "Oto", "Pia", "Quin", "Rex",
        "Sol", "Tia",
    ];
    const LAST: [&str; 26] = [
        "Abbott", "Brooks", "Castro", "Diaz", "Evans", "Fox", "Gray", "Hale", "Ito", "Jones", "Khan", "Lund", "Moss", "Nash", "Ortiz",
        "Park", "Quinn", "Reyes", "Stone", "Toth", "Ueda", "Voss", "Wolfe", "Xu", "Young", "Zhou",
    ];
    s.based_on("default", default)?;
    s.at(NOW - days(20));
    let digest: String =
        s.conn()
            .query_row("SELECT password_digest FROM users WHERE password_digest IS NOT NULL ORDER BY id LIMIT 1", [], |row| row.get(0))?;
    let open_rooms: Vec<i64> = Room::of_type(s.conn(), RoomType::Open)?.into_iter().map(|room| room.id).collect();

    // `User.insert_all!`, then what `User#grant_membership_to_open_rooms` does for each of them.
    let mut ids = Vec::new();
    for i in 0..520 {
        let time = campfire_db::Timestamp::from_jiff(NOW - days(20) + minutes(i));
        let name = format!("{} {}", FIRST[i as usize % FIRST.len()], LAST[i as usize / FIRST.len()]);
        let email = format!("member{:03}@example.com", i + 1);
        s.execute(
            "INSERT INTO users (name, email_address, password_digest, role, status, created_at, updated_at) VALUES (?1, ?2, ?3, 0, 0, ?4, ?4)",
            rusqlite::params![name, email, digest, time],
        )?;
        let id = s.conn().last_insert_rowid();
        for room in &open_rooms {
            s.execute(
                "INSERT INTO memberships (room_id, user_id, involvement, created_at, updated_at) VALUES (?1, ?2, 'mentions', ?3, ?3)",
                rusqlite::params![room, id, time],
            )?;
        }
        ids.push(id);
    }
    s.label("users", "crowd_first", ids[0]);
    s.label("users", "crowd_last", ids[ids.len() - 1]);
    Ok(())
}

