/// The base of the URLs in a [`render_detached_at`] during a request. `SetCurrentRequest`'s
/// `default_url_options` only carries `request.host` and `request.protocol`, so the port comes
/// from the renderer's own env (`example.org:80`) and never shows: a request to
/// `http://localhost:3999` broadcasts `http://localhost/...` links.
pub fn renderer_base_url(c: &Ctx) -> String {
    format!("{}{}", c.request.protocol(), c.request.host())
}

/// Renders with the `ViewContext` `ApplicationController.render` has (no request, no
/// `Current.user`, no CSRF tokens), during a request: URLs get the request's host through
/// `default_url_options` (`SetCurrentRequest`), see [`renderer_base_url`].
pub fn render_detached_at<T>(app: &App, account: Option<&Account>, base_url: &str, render: impl FnOnce(&ViewContext) -> T) -> T {
    let asset_path = |path: &str| campfire_assets::asset_path(path);
    let stylesheets = crate::controllers::presenters::view_context::stylesheet_tags();
    let ctx = ViewContext {
        current_user: None,
        account: account_summary(account, false),
        flash_notice: None,
        flash_alert: None,
        platform: Platform::default(),
        vapid_public_key: app.vapid_public_key(),
        asset_path: &asset_path,
        importmap_tags: campfire_assets::javascript_importmap_tags(),
        stylesheet_tags: &stylesheets.html,
        custom_styles: None,
        cable_url: "/cable".into(),
        base_url: base_url.to_string(),
        request_url: format!("{base_url}/"),
        referrer: None,
        last_room_visited_id: None,
        app_version: app.config.app_version.clone(),
    };
    // Renders outside a request (broadcasts from jobs) share the fragment cache too.
    campfire_views::fragment_cache::with(&app.fragment_cache, || render(&ctx))
}
//! The jobs integrations perform for the app's job runner: `Room::PushMessageJob`.

use campfire_db::{Database, Event, Message, PushSubscription};

use super::net::Network;
use super::web_push::{self, VapidConfig, VapidError};
use crate::app::App;
use crate::config::Config;
use crate::jobs::{JobKind, Registry};

/// Registers the handler for `Event::PushMessage`.
pub fn register_jobs(registry: &mut Registry) {
    registry.handle(JobKind::PushMessage, push_message);
}

/// `Room::PushMessageJob#perform(room, message)`: `Room::MessagePusher.new(room:, message:).push`,
/// unless Web Push is off.
async fn push_message(app: App, event: Event) -> anyhow::Result<()> {
    let Event::PushMessage { message_id, .. } = event else { return Ok(()) };
    let Some(pool) = app.web_push.clone() else { return Ok(()) };
    let db = app.db.clone();
    // Offloaded: it encrypts a notification for every subscriber.
    app.db
        .read_offloaded(move |conn| {
            let message = Message::find(conn, message_id)?;
            web_push::push_message(&pool, conn, &*db.env().rich_text, &message, db.env().now()).map(|_| ())
        })
        .await?;
    Ok(())
}

/// config/initializers/web_push.rb (`config.x.web_push_pool`): the pool, whose invalid
/// subscription handler destroys the subscription (`Push::Subscription.find_by(id:)&.destroy`).
/// `None`, and Web Push is off, when the VAPID keys are missing or invalid. Call from inside the
/// runtime.
pub fn web_push_pool(config: &Config, db: &Database) -> Option<web_push::Pool> {
    let vapid = match VapidConfig::from_config(config) {
        Ok(vapid) => vapid,
        Err(error @ VapidError::Missing) => {
            tracing::warn!("Web Push is off: {error}");
            return None;
        }
        Err(error) => {
            tracing::error!("Web Push is off: {error}");
            return None;
        }
    };
    let db = db.clone();
    Some(web_push::Pool::new(Network::system(), vapid, move |id| {
        db.write_blocking(move |tx| match PushSubscription::find(tx.conn(), id) {
            Ok(subscription) => subscription.destroy(tx),
            Err(campfire_db::Error::RecordNotFound(_)) => Ok(()),
            Err(error) => Err(error),
        })
    }))
}
