    pub fn to_s(&self) -> Option<String> {
        match self {
            Param::Null => Some(String::new()),
            Param::Bool(b) => Some(b.to_string()),
            Param::Number(n) => Some(n.to_string()),
            Param::Str(s) => Some(s.clone()),
