        // Add bot to closed room manually via its edit form ids.
        let room_members_before = app.db().read(move |conn| Ok(campfire_db::Room::find(conn, ALL_TALK).unwrap().user_ids(conn).unwrap())).await.unwrap();
        assert!(!room_members_before.contains(&bot_user_id));
