        // The test Req::form takes &[(&str,&str)]; build manually.
        let _ = req;
        // Instead grant via direct write + manual notify path is covered by controller; here use PATCH with proper encoding.
        // Build body manually to include repeated keys.
        let body = room_members_before.iter().map(|id| format!("room%5Buser_ids%5D%5B%5D={id}")).collect::<Vec<_>>().join("&") + &format!("&room%5Buser_ids%5D%5B%5D={bot_user_id}");
        let reply = david.write(crate::controllers::presenters::test_support::Req { method: Method::PATCH, path: format!("/rooms/closeds/{ALL_TALK}"), headers: vec![("content-type".into(), "application/x-www-form-urlencoded".into())], body: body.into_bytes() }).await;
        assert!(reply.status == StatusCode::FOUND || reply.status == StatusCode::SEE_OTHER, "{} {}", reply.status, reply.text());
        let payloads = wait_for(&seen, before + 1).await;
        assert_eq!(payloads.len(), before + 1, "manual add sends joined: {payloads:?}");
        assert_eq!(payloads.last().unwrap()["event"], "joined");
        assert_eq!(payloads.last().unwrap()["room"]["id"], ALL_TALK);
    }

