        let payloads = wait_for(&seen, 1).await;
        assert!(!payloads.is_empty());
        assert_eq!(payloads[0]["event"], "joined");
        assert_eq!(payloads[0]["room"]["reply_to"], serde_json::Value::String(format!("/rooms/{}/{}/messages", payloads[0]["room"]["id"].as_i64().unwrap(), bot_code)));
        // Reply posted into that room as the bot.
        let db = app.db().clone();
        let rich = app.booted.app.db.env().rich_text.clone();
        let mut found = false;
        for _ in 0..200 {
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
            let msgs = db.read(move |conn| campfire_db::Message::for_room(conn, HQ)).await.unwrap();
            for m in msgs.iter().filter(|m| m.creator_id == bot_user_id) {
                let mid = m.id; let r2 = rich.clone();
                let plain = db.read(move |conn| Ok(campfire_db::Message::find(conn, mid).unwrap().plain_text_body(conn, &*r2).unwrap())).await.unwrap();
                if plain.contains("hello from joined") { found = true; break; }
            }
            if found { break; }
        }
        assert!(found, "joined reply posted");
        // Direct never triggers: add bot to direct via model + controller path would skip.
        seen.lock().unwrap().clear();
        let direct_before = seen.lock().unwrap().len();
        // Try to add bot to direct through find_or_create (model level, no notify) - ensure our controllers never notify for directs.
        // Simulate manual direct grant via Room::grant_to then ensure no notify helper would fire (notify_after_join skips directs).
        let room = app.db().read(move |conn| Ok(campfire_db::Room::find(conn, DIRECT_DAVID_JASON).unwrap())).await.unwrap();
        let bot = app.db().read(move |conn| Ok(campfire_db::Bot::find(conn, bot_id).unwrap())).await.unwrap();
        crate::bot_webhooks::notify_after_join(&app.booted.app, &room, &bot, "http://campfire.test");
        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
        assert_eq!(seen.lock().unwrap().len(), direct_before, "direct never notifies");
        // New open room notifies opted-in bot exactly once.
        seen.lock().unwrap().clear();
        let reply = david.write(Req::new(Method::POST, "/rooms/opens").form(&[("room[name]", "New Open")])).await;
        assert!(reply.status == StatusCode::FOUND || reply.status == StatusCode::SEE_OTHER, "{} {}", reply.status, reply.text());
        let payloads = wait_for(&seen, 1).await;
        assert_eq!(payloads.len(), 1, "new open notifies once: {payloads:?}");
        assert_eq!(payloads[0]["event"], "joined");
        let _ = ALL_TALK;
    }

