    let app = c.app().clone();
    let base_url = page::renderer_base_url(c);
    let room = room.clone();
    let html = c
        .app()
        .read(move |conn| {
            let presenter = Presenter::new(conn, &app, None);
            let sidebar_room = presenter.sidebar_room(&room);
