enum Stored {
    Params,
    Array(Vec<Param>),
    Nil,
}

impl Stored {
    fn into_param(self, params: ParamMap) -> Param {
        match self {
            Stored::Params => Param::Hash(params),
            Stored::Array(items) => Param::Array(items),
            Stored::Nil => Param::Null,
